  cursor: default;
}
@media (max-width: 600px) {
  .member-identity-title {
    align-items: flex-start;
    gap: 12px;
  }
  .member-identity .profile-type {
    margin-top: 7px;
  }
  .member-identity > p {
    display: grid;
    gap: 6px;
  }
  .member-identity > p span {
    border: 0;
    padding: 0;
  }
  .member-tabs {
    gap: 22px;
    font-size: 0.9rem;
  }
  .currency-heading {
    display: grid;
    gap: 10px;
  }
  .currency-total {
    text-align: left;
  }
  .category-column-heading {
    display: none;
  }
  .category-label {
    display: grid;
    gap: 6px;
  }
  .category-label .amount {
    text-align: left;
  }
  .history-filters {
    gap: 12px;
  }
  .history-filters label {
    flex: 1;
    min-width: 130px;
  }
  .history-filters input {
    width: 100%;
    min-width: 0;
  }
}
